import { Mesh, PlaneGeometry, Object3D, Texture } from 'three/webgpu';
import {
    MeshBasicNodeMaterial,
    textureNode
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @param {Object} config - Node configuration
 * @param {Object} ctx - Node context providing loaders and primitives
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // ----- Asset loading -------------------------------------------------
    const imageUrl = config.assets?.imageUrl;
    const texture = imageUrl ? ctx.textureLoader(imageUrl) : null;

    // ----- Atlas region handling -----------------------------------------
    // Expected format in config:
    // config.atlasRegion = { atlas: 0, sourceRect: { x:0, y:0, width:512, height:320 } }
    const sourceRect = (config.atlasRegion && config.atlasRegion.sourceRect) || {
        x: 0,
        y: 0,
        width: 512,
        height: 320
    };

    // Apply UV offset / repeat based on atlas region if texture is ready
    if (texture && texture.image) {
        const img = texture.image;
        const texWidth = img.width;
        const texHeight = img.height;

        const repeatX = sourceRect.width / texWidth;
        const repeatY = sourceRect.height / texHeight;
        const offsetX = sourceRect.x / texWidth;
        // three.js UV origin is bottom‑left, atlas origin is assumed top‑left
        const offsetY = 1 - (sourceRect.y + sourceRect.height) / texHeight;

        texture.repeat.set(repeatX, repeatY);
        texture.offset.set(offsetX, offsetY);
        texture.needsUpdate = true;
    }

    // ----- Geometry -------------------------------------------------------
    const aspect = sourceRect.width / sourceRect.height;
    const geometry = new PlaneGeometry(aspect, 1);

    // ----- Material --------------------------------------------------------
    const material = new MeshBasicNodeMaterial();
    if (texture) {
        material.map = textureNode(texture);
    }
    material.transparent = true;
    material.depthWrite = false;

    // ----- Mesh ------------------------------------------------------------
    const mesh = new Mesh(geometry, material);
    mesh.position.set(
        config.position?.[0] ?? 0,
        config.position?.[1] ?? 0,
        config.position?.[2] ?? 0
    );
    mesh.rotation.set(
        config.rotation?.[0] ?? 0,
        config.rotation?.[1] ?? 0,
        config.rotation?.[2] ?? 0
    );
    mesh.scale.set(
        config.scale?.[0] ?? 1,
        config.scale?.[1] ?? 1,
        config.scale?.[2] ?? 1
    );

    // ----- Billboard behaviour --------------------------------------------
    mesh.onBeforeRender = (renderer, scene, camera) => {
        mesh.quaternion.copy(camera.quaternion);
    };

    // ----- Event handlers placeholder ---------------------------------------
    mesh.userData.handlers = {};

    // ----- Cleanup ---------------------------------------------------------
    mesh.userData.cleanup = () => {
        geometry.dispose();
        material.dispose();
        if (texture instanceof Texture) {
            texture.dispose();
        }
        // Kill any GSAP timelines that might have been attached in the future
        gsap.globalTimeline.clear();
    };

    return mesh;
}
